package com.pethop.user;
import com.pethop.common.response.PageResponse; import com.pethop.security.SecurityUser; import com.pethop.user.dto.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.UUID; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/users") public class AdminUserController{private final AdminUserService service;public AdminUserController(AdminUserService s){service=s;}@GetMapping PageResponse<AdminUserResponse> list(@RequestParam(required=false)String search,@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="25")@Min(1)@Max(100)int size){return service.list(search,page,size);}@GetMapping("/{id}")AdminUserResponse get(@PathVariable UUID id){return service.get(id);}@PatchMapping("/{id}/status")AdminUserResponse change(@PathVariable UUID id,@AuthenticationPrincipal SecurityUser admin,@Valid @RequestBody AdminUserActionRequest request){return service.change(id,admin,request);}}
